<script setup lang="ts">
import { Activity, Building2, ChevronDown, ChevronLeft, ChevronRight, Filter, Search, ShieldCheck, UserRound, X } from '@lucide/vue'
import { onMounted, reactive, ref } from 'vue'
import api from '../api'
const emit=defineEmits<{close:[]}>();const loading=ref(true);const error=ref('');const data=ref<any>({logs:[],events:[],actors:[],branches:[],pagination:{page:1,last_page:1,total:0}});const open=ref<number|null>(null);const filters=reactive({event:'',actor_id:'',branch:'',search:'',page:1,per_page:25})
const eventLabel=(event:string)=>event.split('.').map(part=>part.split('_').join(' ')).join(' · ');const dateLabel=(value:string)=>new Intl.DateTimeFormat('en-EG',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))
async function load(){loading.value=true;error.value='';try{data.value=(await api.get('/audit-logs',{params:{...filters,page:filters.page}})).data;open.value=null}catch(e:any){error.value=e.response?.data?.message||'Unable to load the audit history.'}finally{loading.value=false}}
function apply(){filters.page=1;load()}function reset(){Object.assign(filters,{event:'',actor_id:'',branch:'',search:'',page:1});load()}function move(page:number){if(page<1||page>data.value.pagination.last_page||loading.value)return;filters.page=page;load()}
onMounted(load)
</script>
<template><div class="modal-backdrop audit-backdrop" @click.self="emit('close')"><section class="audit-modal" role="dialog" aria-modal="true" aria-labelledby="audit-title"><header class="audit-modal-head"><div><span><ShieldCheck/></span><div><small>SECURITY & ACCOUNTABILITY</small><h2 id="audit-title">Organisation audit history</h2><p>A read-only record of sensitive access, centre and academic changes.</p></div></div><button @click="emit('close')"><X/></button></header><form class="audit-filters" @submit.prevent="apply"><label class="audit-search"><Search/> <input v-model="filters.search" placeholder="Search event, actor or target"></label><label><Activity/>Event<select v-model="filters.event"><option value="">All events</option><option v-for="event in data.events" :key="event" :value="event">{{eventLabel(event)}}</option></select></label><label><UserRound/>Actor<select v-model="filters.actor_id"><option value="">All people</option><option v-for="actor in data.actors" :key="actor.id" :value="actor.id">{{actor.name}}</option></select></label><label><Building2/>Centre<select v-model="filters.branch"><option value="">All centres</option><option v-for="branch in data.branches" :key="branch.public_id" :value="branch.public_id">{{branch.name_en||branch.name_ar}}</option></select></label><button class="button primary"><Filter/>Apply</button><button type="button" class="audit-reset" @click="reset">Reset</button></form><div v-if="error" class="form-error audit-error">{{error}}</div><div v-if="loading" class="team-modal-loading"><span></span>Loading verified activity…</div><div v-else class="audit-content"><div class="audit-result-head"><span><Search/>{{data.pagination.total}} events</span><small>Page {{data.pagination.page}} of {{data.pagination.last_page}}</small></div><div v-if="data.logs.length" class="audit-rows"><article v-for="log in data.logs" :key="log.id" :class="{open:open===log.id}"><button class="audit-row-main" @click="open=open===log.id?null:log.id"><span class="audit-event-icon"><Activity/></span><span class="audit-event"><b>{{eventLabel(log.event)}}</b><small>{{log.target_type||'System'}}{{log.target_id?' #'+log.target_id:''}}</small></span><span class="audit-actor"><b>{{log.actor?.name||'System'}}</b><small>{{log.actor?.email||log.ip_address||'Automated action'}}</small></span><span class="audit-branch"><Building2/>{{log.branch?.name_en||log.branch?.name_ar||'Organisation-wide'}}</span><time>{{dateLabel(log.created_at)}}</time><ChevronDown/></button><div v-if="open===log.id" class="audit-details"><div><small>BEFORE</small><pre>{{JSON.stringify(log.before||{},null,2)}}</pre></div><div><small>AFTER</small><pre>{{JSON.stringify(log.after||{},null,2)}}</pre></div></div></article></div><div v-else class="audit-empty"><ShieldCheck/><b>No events match these filters</b><p>Try resetting the filters or return after an administrative change.</p></div><div class="audit-pagination"><button class="button secondary" :disabled="filters.page<=1||loading" @click="move(filters.page-1)"><ChevronLeft/>Previous</button><span>{{data.pagination.total}} total</span><button class="button secondary" :disabled="filters.page>=data.pagination.last_page||loading" @click="move(filters.page+1)">Next<ChevronRight/></button></div></div></section></div></template>
